// Which syllable type each state accepts, if any.
pub(crate) static INDIC_ACCEPTS: [u8; 137] = [
    5, 4, 0, 1, 5, 5, 4, 4, 5, 5, 5, 2, 5, 5, 0, 5, 3, 4, 4, 0, 0, NONE, 0, 0, 0, 0, 0, 0, 1, 1, NONE, 1, 1, 1, 1, 1, 1, 5, NONE, 5, 5, 5, 5, 5, NONE, 5, 5, NONE, 5, 2, 2, NONE, NONE, 2, 2, 2, 2, 2, NONE, 0, 5, NONE, 3, NONE, 3, 3, 0, NONE, 0, 0, 0, 0, NONE, 0, 0, NONE, 0, 0, NONE, 1, NONE, 1, 1, 1, 1, 1, NONE, 1, 1, NONE, 1, 1, NONE, 5, NONE, 5, NONE, 2, 2, 2, 2, 2, 2, NONE, 2, 2, NONE, 2, 2, NONE, 0, 0, 0, 5, 5, 3, NONE, 0, NONE, 0, 0, 1, NONE, 1, 1, NONE, 1, NONE, 1, 1, NONE, 2, NONE, 2, 2, NONE, 1,
];

pub(crate) fn indic_accept(state: u16) -> Option<IndicSyllable> {
    IndicSyllable::from_index(*INDIC_ACCEPTS.get(state as usize)?)
}

// `khmer` syllable types, in the grammar's own order.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[allow(clippy::enum_variant_names)]
pub(crate) enum KhmerSyllable {
    ConsonantSyllable,
    BrokenCluster,
    NonKhmerCluster,
}

impl KhmerSyllable {
    fn from_index(i: u8) -> Option<Self> {
        Some(match i {
            0 => KhmerSyllable::ConsonantSyllable,
            1 => KhmerSyllable::BrokenCluster,
            2 => KhmerSyllable::NonKhmerCluster,
            _ => return None,
        })
    }
}

impl From<KhmerSyllable> for u8 {
    fn from(s: KhmerSyllable) -> u8 {
        match s {
            KhmerSyllable::ConsonantSyllable => 0,
            KhmerSyllable::BrokenCluster => 1,
            KhmerSyllable::NonKhmerCluster => 2,
        }
    }
}

