// Which syllable type each state accepts, if any.
pub(crate) static KHMER_ACCEPTS: [u8; 44] = [
    1, 2, 0, 1, 2, 0, 1, 1, 1, 1, 1, 1, 1, 0, NONE, 0, 0, 0, 0, 0, 0, 1, NONE, NONE, 0, NONE, NONE, NONE, NONE, NONE, NONE, 0, NONE, NONE, NONE, NONE, NONE, NONE, NONE, NONE, NONE, NONE, NONE, NONE,
];

pub(crate) fn khmer_accept(state: u16) -> Option<KhmerSyllable> {
    KhmerSyllable::from_index(*KHMER_ACCEPTS.get(state as usize)?)
}

// `lana` syllable types, in the grammar's own order.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[allow(clippy::enum_variant_names)]
pub(crate) enum LanaSyllable {
    ViramaTerminatedCluster,
    SakotTerminatedCluster,
    StandardCluster,
    NumberJoinerTerminatedCluster,
    NumeralCluster,
    SymbolCluster,
    HieroglyphCluster,
    NonCluster,
    BrokenCluster,
}

impl LanaSyllable {
    fn from_index(i: u8) -> Option<Self> {
        Some(match i {
            0 => LanaSyllable::ViramaTerminatedCluster,
            1 => LanaSyllable::SakotTerminatedCluster,
            2 => LanaSyllable::StandardCluster,
            3 => LanaSyllable::NumberJoinerTerminatedCluster,
            4 => LanaSyllable::NumeralCluster,
            5 => LanaSyllable::SymbolCluster,
            6 => LanaSyllable::HieroglyphCluster,
            7 => LanaSyllable::NonCluster,
            8 => LanaSyllable::BrokenCluster,
            _ => return None,
        })
    }
}

impl From<LanaSyllable> for u8 {
    fn from(s: LanaSyllable) -> u8 {
        match s {
            LanaSyllable::ViramaTerminatedCluster => 0,
            LanaSyllable::SakotTerminatedCluster => 1,
            LanaSyllable::StandardCluster => 2,
            LanaSyllable::NumberJoinerTerminatedCluster => 3,
            LanaSyllable::NumeralCluster => 4,
            LanaSyllable::SymbolCluster => 5,
            LanaSyllable::HieroglyphCluster => 6,
            LanaSyllable::NonCluster => 7,
            LanaSyllable::BrokenCluster => 8,
        }
    }
}

